#include "AgentHttp.h"
namespace AgentHttp { static juce::String req(const juce::String&u,const juce::String&m,const juce::String&j,int t){juce::URL url(u);auto o=juce::URL::InputStreamOptions(juce::URL::ParameterHandling::inAddress).withHttpRequestCmd(m).withExtraHeaders("Accept: application/json\r\nContent-Type: application/json\r\n").withConnectionTimeoutMs(t);std::unique_ptr<juce::InputStream>s;if(m=="POST")s=url.withPOSTData(j).createInputStream(o);else s=url.createInputStream(o);return s?s->readEntireStreamAsString():R"({"ok":false,"error":"HTTP request failed"})";}juce::String get(const juce::String&u,int t){return req(u,"GET",{},t);}juce::String post(const juce::String&u,const juce::String&j,int t){return req(u,"POST",j,t);} }
